B=set(blocks)
dots=[(r,c,v) for r in range(12) for c in range(12) if inp[r][c] not in (0,2)]

def sim(order='given', emit='away', bounce_edge='flip', stop_at_dot=True, color_cycle=None, through_block=False):
    g=[row[:] for row in out]
    for r in range(12):
        for c in range(12):
            g[r][c]=0
    for r,c in B: g[r][c]=2
    ds = dots if order=='given' else dots[::-1]
    cyc=[3,8,7,6]
    for r,c,v in ds:
        if emit=='away':
            # direction away from adjacent block corner
            dirs=[]
            for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
                rr,cc=r+dr,c+dc
                if 0<=rr<12 and 0<=cc<12 and (rr,cc) in B:
                    dirs.append((-dr,-dc))
            use=dirs
        else:
            use=[(-1,-1),(-1,1),(1,-1),(1,1)]
        col=v
        for dr,dc in use:
            rr,cc=r,c
            n=0
            while 0<=rr<12 and 0<=cc<12 and n<60:
                n+=1
                nr,nc=rr+dr,cc+dc
                if (nr,nc) in B:
                    if not through_block: break
                    # pass through: skip block cells along diagonal
                    while (nr,nc) in B: nr+=dr; nc+=dc
                    rr,cc=nr,nc
                    continue
                if not (0<=nr<12 and 0<=nc<12):
                    # edge bounce
                    ndr,ndc=dr,dc
                    if not (0<=nr<12): ndr=-dr
                    if not (0<=nc<12): ndc=-dc
                    if color_cycle is not None:
                        col=cyc[(cyc.index(col)+1)%4]
                    dr,dc=ndr,ndc
                    continue
                if (nr,nc) in B: continue
                if stop_at_dot and inp[nr][nc] not in (0,2):
                    # passes over dot: overwrite it
                    g[nr][nc]=col
                    break
                g[nr][nc]=col
                rr,cc=nr,nc
            # also color the dot itself? 
    return g

def score(g):
    s=0
    for r in range(12):
        for c in range(12):
            if g[r][c]!=out[r][c]: s+=1
    return s

