def predict(gin):
    H,W=len(gin),len(gin[0])
    g=[[0]*W for _ in range(H)]
    # find blocks (2x2 of 2s)
    blocks=[]
    for r in range(H-1):
        for c in range(W-1):
            if all(gin[r+dr][c+dc]==2 for dr in (0,1) for dc in (0,1)):
                blocks.append((r,c))
    for r,c in blocks:
        for dr in (0,1):
            for dc in (0,1):
                g[r+dr][c+dc]=2
    # corners: TL,TR,BR,BL ; dot at corner = cell diagonally outward-inward (inside diag)
    # dots: cell diagonally adjacent inward: for TL corner (r,c) dot at (r-1,c-1), etc.
    corner_defs=[('TL',0,0,-1,-1),('TR',0,1,-1,2),('BR',1,1,2,2),('BL',1,0,2,-1)]
    # outward dirs: TL->(-1,-1), TR->(-1,+1), BR->(+1,+1), BL->(+1,-1)
    outd={'TL':(-1,-1),'TR':(-1,1),'BR':(1,1),'BL':(1,-1)}
    for r,c in blocks:
        dotcol={}
        for name,dr,dc,dotr,dotc in corner_defs:
            rr,cc=r+dotr,c+dotc
            dotcol[name]=gin[rr][cc] if 0<=rr<H and 0<=cc<W else 0
        # shift: ray at corner X = dot color at previous corner in CW order TL->TR->BR->BL->TL
        order=['TL','TR','BR','BL']
        prev={order[i]:order[i-1] for i in range(4)}
        for name,dr,dc,_,_ in corner_defs:
            col=dotcol[prev[name]]
            ddr,ddc=outd[name]
            rr,cc=r+dr+ddr, c+dc+ddc  # first cell outside corner? corner at (r+dr,c+dc); ray starts diag outward
            while 0<=rr<H and 0<=cc<W:
                g[rr][cc]=col
                rr+=ddr; cc+=ddc
    return g

